function sendFilesToPySide(filesData) {
  if (Array.isArray(filesData) && filesData.length > 0) {
    chrome.runtime.sendMessage({
      type: "SEND_WS_DATA",
      payload: {
        action: "save_files_batch",
        files: filesData
      }
    }, (res) => {
      if (res && res.status === "error") {
        console.warn("[Extension] 发送数据失败:", res.message);
      }
    });
  }
